%% stem_01_dft_vs_expt_voltage.m - DFT vs experimental conversion voltages
% Generated by tools/matlab/make_stem.py from sim/s11_dft_chlorides/out/s11_results.json. Values: [SIMULATED] vs [PUBLISHED].
% Runs in MATLAB R2019b+ and GNU Octave 8+. Output: out/stem_01_dft_vs_expt_voltage.png
if exist('OCTAVE_VERSION', 'builtin'), graphics_toolkit('gnuplot'); end   % Octave only; MATLAB skips this line
fig = figure('Visible', 'off', 'Color', 'w', 'Position', [100 100 960 520]);
set(fig, 'PaperPositionMode', 'auto');
hold on; grid on; box off;
try, set(gca, 'GridColor', [0.80 0.80 0.80], 'GridAlpha', 0.6); catch, end
x = 1:4;
dft = [3.92 2.598 2.915 2.848];
expH = [4.261 2.49 2.642 2.679];
h1 = stem(x - 0.12, dft, 'filled', 'LineWidth', 3, 'Color', [0.165 0.471 0.839], 'MarkerFaceColor', [0.165 0.471 0.839], 'MarkerSize', 8);
h2 = stem(x + 0.12, expH, 'LineWidth', 3, 'Color', [0.922 0.408 0.204], 'MarkerSize', 8);
set(gca, 'XTick', 1:4, 'XTickLabel', {'Na + 1/2 Cl_2', 'FeCl_2 (U=0)', 'CoCl_2 (U=0)', 'NiCl_2 (U=0)'});
try, set(gca, 'XTickLabelRotation', 35); catch, end
xlim([0.4 4.6]); ylim([0 4.6]); ylabel('Voltage vs Na (V)');
title('Na-metal-chloride couples: PBE (U = 0) vs experiment (\DeltaH, 298 K)');
legend([h1 h2], {'DFT (PBE-D3)', 'Experiment (\DeltaH)'}, 'Location', 'northeast');
set(gca, 'FontSize', 11, 'LineWidth', 0.8);
if ~exist('out', 'dir'), mkdir('out'); end
print(fig, fullfile('out', 'stem_01_dft_vs_expt_voltage.png'), '-dpng', '-r200');
close(fig);
